/**
 * Dashboard Component
 * Affiche les statistiques, journal de présence et taux d'attendance
 */

import React, { useState, useEffect, useMemo } from "react";
import { attendanceAPI, studentsAPI } from "./api_service";

const COLORS = {
  primary: "#4F46E5",
  success: "#10B981",
  danger: "#EF4444",
  warning: "#F59E0B",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0"
};

const Dashboard = () => {
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Load data on component mount
  useEffect(() => {
    loadData();
    // Refresh every 10 seconds
    const interval = setInterval(loadData, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);

      // Get attendance statistics
      const statsRes = await attendanceAPI.getStats();
      setStats(statsRes.data);

      // Get today's attendance log
      const logRes = await attendanceAPI.getTodayLog();
      setAttendanceLog(logRes.data.records || []);

      // Get present/absent status
      const statusRes = await attendanceAPI.getStatus();
      setStatusList(statusRes.data.students || []);

      setError(null);
    } catch (err) {
      console.error("Error loading dashboard:", err);
      setError("Erreur lors du chargement des données");
    } finally {
      setLoading(false);
    }
  };

  // Compute memoized stats cards
  const statCards = useMemo(() => [
    {
      label: "Total Étudiants",
      value: stats.active_students,
      icon: "👥",
      color: "#4F46E5"
    },
    {
      label: "Présents aujourd'hui",
      value: stats.present_today,
      icon: "✅",
      color: "#10B981"
    },
    {
      label: "Absents aujourd'hui",
      value: stats.absent_today,
      icon: "❌",
      color: "#EF4444"
    },
    {
      label: "Taux de présence",
      value: `${Math.round((stats.present_today / stats.active_students) * 100) || 0}%`,
      icon: "📈",
      color: "#8B5CF6"
    }
  ], [stats]);

  if (loading) {
    return <div style={styles.loading}>⏳ Chargement...</div>;
  }

  return (
    <div style={styles.container}>
      {error && <div style={styles.error}>⚠️ {error}</div>}

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        {statCards.map((stat, i) => (
          <StatCard key={i} stat={stat} />
        ))}
      </div>

      <div style={styles.grid2Col}>
        {/* Attendance Log */}
        <Card title="Journal de présence récent" subtitle="Les 10 dernières entrées détectées">
          <table style={styles.table}>
            <thead>
              <tr style={styles.tableHeader}>
                <th style={styles.th}>Étudiant</th>
                <th style={styles.th}>Heure</th>
                <th style={styles.th}>Confiance</th>
              </tr>
            </thead>
            <tbody>
              {attendanceLog.slice(0, 10).map((record, i) => (
                <tr key={i} style={styles.tableRow}>
                  <td style={styles.td}>{record.student}</td>
                  <td style={styles.td}>{record.timestamp}</td>
                  <td style={styles.td}>
                    <ConfidenceBadge value={record.confidence} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </Card>

        {/* Summary Stats */}
        <Card title="Résumé de la journée" subtitle="Statistiques détaillées">
          <div style={styles.summaryBox}>
            <SummaryItem
              label="Enregistrements uniques"
              value={stats.summary.unique_students}
            />
            <SummaryItem
              label="Total des scans"
              value={stats.summary.total_records}
            />
            <SummaryItem
              label="Confiance moyenne"
              value={`${(stats.summary.avg_confidence * 100).toFixed(1)}%`}
            />
            <SummaryItem
              label="Confiance max"
              value={`${(stats.summary.max_confidence * 100).toFixed(1)}%`}
            />
          </div>
        </Card>
      </div>

      {/* Status Table */}
      <Card
        title="État de présence - Tous les étudiants"
        subtitle={`${stats.present_today} présents, ${stats.absent_today} absents`}
      >
        <table style={styles.table}>
          <thead>
            <tr style={styles.tableHeader}>
              <th style={styles.th}>Nom</th>
              <th style={styles.th}>Email</th>
              <th style={styles.th}>Statut</th>
            </tr>
          </thead>
          <tbody>
            {statusList.map((student, i) => (
              <tr key={i} style={styles.tableRow}>
                <td style={styles.td}>{student.name}</td>
                <td style={styles.td}>{student.email || "N/A"}</td>
                <td style={styles.td}>
                  <Badge present={student.present} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>

      {/* Refresh Button */}
      <button onClick={loadData} style={styles.refreshBtn}>
        🔄 Rafraîchir
      </button>
    </div>
  );
};

